lab.starterCode:
progress = {'python': {'done': 2, 'total': 5}, 'sql': {'done': 1, 'total': 4}}
change = {'done': 3}

# Make an updated python record without losing its total.
# Keep sql unchanged.
# Print course names and done counts in insertion order.
# Print the unchanged original python record.

lab.solution:
progress = {'python': {'done': 2, 'total': 5}, 'sql': {'done': 1, 'total': 4}}
change = {'done': 3}
new_python = progress['python'] | change
updated = progress | {'python': new_python}
for course, data in updated.items():
    print(f"{course}: {data['done']}/{data['total']}")
print(progress['python'])
